require_once __DIR__.'/../includes/verificar_sesion.php';$roles_permitidos=['administrador'];require_once __DIR__.'/../includes/verificar_rol.php';require_once __DIR__.'/../config/conexion.php';$q=$pdo->query('SELECT r.*,s.marca,s.modelo,s.problema_reportado,e.nombre AS especialista,c.nombre AS cliente FROM reparaciones r JOIN solicitudes s ON s.id_solicitud=r.id_solicitud JOIN usuarios e ON e.id_usuario=r.id_especialista JOIN usuarios c ON c.id_usuario=s.id_cliente ORDER BY r.id_reparacion DESC');$reparaciones=$q->fetchAll();$titulo_pagina='Reparaciones';$ruta_base='../';require_once __DIR__.'/../includes/encabezado.php';
?><div class="cabecera-panel"><div><span class="etiqueta">TALLER</span><h1>Reparaciones</h1><p>Monitorea el trabajo técnico en curso.</p></div></div><section class="tabla-contenedor"><table class="tabla"><thead><tr><th>ID</th><th>Cliente / Consola</th><th>Especialista</th><th>Problema</th><th>Inicio</th><th>Estado</th></tr></thead><tbody><?php if(!$reparaciones): ?><tr><td colspan="6" class="vacio">No hay reparaciones asignadas.</td></tr><?php else: foreach($reparaciones as $r): ?><tr><td>#<?= $r['id_reparacion'] ?></td><td><strong><?= escapar($r['cliente']) ?></strong><br><?= escapar($r['marca'].' '.$r['modelo']) ?></td><td><?= escapar($r['especialista']) ?></td><td><?= escapar($r['problema_reportado']) ?></td><td><?= $r['fecha_inicio']?date('d/m/Y H:i',strtotime($r['fecha_inicio'])):'Pendiente' ?></td><td><span class="<?= estado_clase($r['estado']) ?>"><?= escapar($r['estado']) ?></span></td></tr><?php endforeach; endif; ?></tbody></table></section><?php require_once __DIR__.'/../includes/pie.php'; ?>

